function replay(list){let state={...(base||window.pactScenario.getInput())};for(const r of list)if(r.applied)state=PactChat.apply(state,r.event);return state;}
function evidenceText(r){const status=r.applied?(r.manual?tr('human interpretation confirmed','подтверждена ручная трактовка'):tr('confirmed','подтверждено')):tr('awaiting review','на проверке');const mapping=r.applied&&r.event?' · '+code(r.event.caseId)+' · '+actionName(r.event.action)+' · '+eventValue(r.event):'';return r.text+' ['+status+mapping+']';}
