 act.onchange=fields;order.onchange=fields;fields();
 const att=el('input');att.type='checkbox';const attest=el('label',tr('I checked that this interpretation matches the message','Я проверил, что трактовка соответствует сообщению'));attest.append(att);box.append(attest);
 const feedback=el('p'),prepare=el('button',tr('Preview this interpretation','Показать последствия трактовки'));prepare.onclick=()=>{if(!att.checked||!order.value||!act.value){feedback.textContent=tr('Choose the order and meaning, then confirm you checked the source.','Выберите заказ, смысл и подтвердите проверку источника.');return}const value=act.value==='approve'?Number(amount.value):act.value==='claim'?order.value:act.value==='owner'?owner.value:act.value==='withdraw'?'withdrawn':act.value==='confirm_date'?'accepted':'requested';if(act.value==='claim'&&Number(amount.value)!==300){feedback.textContent=tr('Only EUR 300 cumulative claims are supported here.','Здесь поддерживается только заявление об отправке всего 300 евро.');return}const candidate={caseId:order.value,action:act.value,value,role:r.role};try{const next=replay(records.map(x=>x.id===r.id?{...x,event:candidate,applied:true}:x));PactCase.evaluate(next);r.event=candidate;r.manual=true;renderLog();$('chat-status').textContent=tr('Human interpretation prepared, not yet applied. Inspect the preview and confirm.','Ручная трактовка подготовлена, но не применена. Проверьте последствия и подтвердите.');}catch(e){feedback.textContent=friendlyError(e)}};box.append(prepare,feedback);return box;
